def ensure_no_private_reports(apps, schema_editor):
    reports = apps.get_model('app', 'TeacherLessonReport').objects.using(schema_editor.connection.alias)
    if reports.exclude(children_list='', photo_link='').exists():
        raise ImproperlyConfigured(
            'Existing lesson reports contain private fields. Use import_legacy_sqlite with a backup.'
        )


def link_municipalities(apps, schema_editor):
    from app.legacy.data import profile_updates
    from app.organizations.directory import municipality_codes

    alias = schema_editor.connection.alias
    directory = apps.get_model('app', 'Municipality').objects.using(alias)
    profile_table = apps.get_model('app', 'Profile')
    codes = municipality_codes()
    directory.bulk_create(
        (directory.model(code=code, name=name) for name, code in codes.items()),
        batch_size=1000,
    )
    profiles = profile_table.objects.using(alias)
    fields = ('pk', 'user__username', 'role', 'surname1', 'name', 'surname2', 'birth_date', 'school', 'region', 'position')
    for profile in list(profiles.values(*fields)):
        changes = profile_updates(profile, profile['user__username'], codes)
        profiles.filter(pk=profile['pk']).update(**changes)


